# Builds the two Launch Call decks:
#   public/deck/launch/index.html      -> standard program
#   public/deck/launch-ppa/index.html  -> pay per appointment (calling framed as optional)
#
# usage: python3 scripts/build-launch-deck.py <repo root>
#
# Source 1: public/deck/quick-start/index.html (itself generated by
#   build-quick-start-deck.py - run that first). We take its engine, CSS and the
#   live pieces (ads phones, funnel survey, lead-alert phone, CRM board, AI chat).
# Source 2: scripts/launch-deck/slides.json - the text boxes of the coach's
#   Google Slides ("Launch Call Presentation"), pulled from its /htmlpresent page.
#   The art behind the text is public/deck/assets/launch/aNN.webp (slide render
#   WITHOUT text). Slides whose original screenshot showed real lead names, a
#   lead's photos or a client's page name are rebuilt live with sample data
#   instead (10, 11, 16, 37, 52, 58) and the board behind the disclaimer on 17
#   is blurred in the art itself.
import copy, json, os, re, sys, html as H

root = sys.argv[1]
SRC = open(os.path.join(root, "public/deck/quick-start/index.html"), encoding="utf-8").read()
RAW = {s["n"]: s for s in json.load(open(os.path.join(root, "scripts/launch-deck/slides.json"), encoding="utf-8"))}
SC = 1.25                      # Google Slides canvas is 1280 wide, our stage is 1600

def part(a, b, src=None):
    src = SRC if src is None else src
    assert src.count(a) == 1, ("start marker", a, src.count(a))
    i = src.index(a); j = src.index(b, i + len(a))
    return src[i:j]

def sub(s, a, b, n=1):
    assert s.count(a) == n, ("replace", a[:70], s.count(a))
    return s.replace(a, b)

