def clean_href(href, text):
    from urllib.parse import urlparse, parse_qs
    u = urlparse(href)
    if u.netloc.endswith("google.com") and u.path == "/url":
        q = parse_qs(u.query).get("q")
        if q: return q[0]
    return href

def fam(f):
    return "'%s'" % f if " " in f else f

def plain(b):
    return "".join(r.get("t", "") for r in b["runs"]).replace("​", "").replace("�", " ").strip("\x0b\n ")

def block_html(b, delay):
    runs = [r for r in b["runs"] if r.get("t")]
    base = next((r for r in runs if r.get("f") and r["t"].strip()), None)
    if not plain(b) or base is None:                   # an empty line the coach used as spacing
        return '<p style="font-size:%spx;line-height:normal">&nbsp;</p>' % px(b["fs"])
    out = []
    for r in runs:
        t = esc(r["t"])
        if not r.get("f"):                             # a bare line break
            out.append(t); continue
        st = []
        if r["w"] != base["w"]: st.append("font-weight:%d" % r["w"])
        if r["c"] != base["c"]: st.append("color:%s" % hexcol(r["c"]))
        if r["s"] != base["s"]: st.append("font-size:%spx" % px(r["s"]))
        if r["f"] != base["f"]: st.append("font-family:%s" % fam(r["f"]))
        if r.get("i"): st.append("font-style:italic")
        if r.get("u"): st.append("text-decoration:underline")
        if r.get("bg"): st.append("background:%s" % hexcol(r["bg"]))
        if TEAM_PHONE in r["t"] and plain(b).startswith("Phone:"):      # slide 30: the coach's own line, when she has one
            t = t.replace(TEAM_PHONE, '<span data-coach-phone>%s</span>' % TEAM_PHONE)
        if r.get("href", "").startswith("mailto:"):
            t = '<a data-coach-email href="mailto:%s">%s</a>' % (TEAM_EMAIL, TEAM_EMAIL)
        elif r.get("href"):
            t = '<a href="%s" target="_blank" rel="noopener">%s</a>' % (H.escape(clean_href(r["href"], r["t"]), quote=True), t)
        out.append('<span style="%s">%s</span>' % (";".join(st), t) if st else t)
    inner = "".join(out)
    for key, url in LINKS.items():
        if plain(b).startswith(key):
            inner = '<a class="btnlink" href="%s" target="_blank" rel="noopener">%s</a>' % (url, inner)
    c = ["rv"]
    if b["tag"] == "li": c += ["li", b["list"] or "ul"]
    st = "animation-delay:%.2fs;font:%d %spx/normal %s;color:%s" % (delay, base["w"], px(base["s"]), fam(base["f"]), hexcol(base["c"]))
    if b["align"] != "left": st += ";text-align:" + b["align"]
    return '<p class="%s" style="%s">%s</p>' % (" ".join(c), st, inner)

def boxes_html(data, n, skip=()):
    """every text box of slide n, in reading order, each paragraph rising in"""
    shapes = sorted(data[n]["shapes"], key=lambda h: (round(h["y"] / 24), h["x"]))
    total = sum(1 for h in shapes for b in h["blocks"] if plain(b))
    step = min(0.12, 1.9 / max(1, total))
    k = 0; out = []
    for h in shapes:
        txt = " ".join(plain(b) for b in h["blocks"]).strip()
        if not txt or any(txt.startswith(s) for s in skip):
            continue
        ps = []
        for b in h["blocks"]:
            ps.append(block_html(b, 0.12 + k * step))
            if plain(b): k += 1
        while ps and ps[-1].endswith("&nbsp;</p>"): ps.pop()          # trailing blank lines
        x = h["x"] * SC
        if x < 52 and h["blocks"][0]["align"] == "left": x = 52      # a box that hung off the left edge
        out.append('<div class="tx" style="left:%spx;top:%spx;width:%spx">%s</div>' % (
            ("%.1f" % x).rstrip("0").rstrip("."), px(h["y"]), px(h["w"]), "".join(ps)))
    return "".join(out)

def find_block(data, n, starts):
    for h in data[n]["shapes"]:
        for b in h["blocks"]:
            if plain(b).startswith(starts): return b
    raise AssertionError(("no block", n, starts))

def chips(n, ppa):
    out = ""
    if n in STEP:
        k = STEP[n]
        dots = "".join('<i class="%s"></i>' % ("cur" if i == k else ("on" if i < k else "")) for i in range(1, 8))
        out += '<div class="stepchip">Step %d <em>of 7</em><span class="dots">%s</span></div>' % (k, dots)
    if ppa and n in CALLING:
        out += '<div class="optchip"><b>Optional</b> &middot; to maximize your results</div>'
    if not out: return ""
    return '<div class="chips rv" style="animation-delay:.05s;%s">%s</div>' % (CHIP_POS.get(n, ""), out)

