def slide_phishing():
    msgs = [
        ("Last warning ⚠️", "We haven’t received your response yet. Your page has been warned for copyright infringement and you should contact and confirm your page. If you do not continue to confirm, our system will automatically block your account.",
         "Contact us for help: business-portal-administration.com/…"),
        ("Dear admin!", "Important notification: your Facebook page is scheduled to be permanently deleted due to a post that violated our trademark rights. If you believe this is a misunderstanding, submit an appeal before we remove it.",
         "Please submit your request here: …"),
        ("*Page limit notification ⚠️!", "Hello admin, some features of your page have been limited. The period is limited to 30 days. If you would like to request a review of this decision, please visit the link and provide specific information.",
         "Verification time is 24–48 hours"),
    ]
    cards = "".join(
        '<div class="scam rv" style="animation-delay:%.2fs"><b>%s</b><p>%s</p><p class="lnk">%s</p>'
        '<span class="stamp" style="animation-delay:%.2fs">SCAM</span></div>' % (0.5 + k * 0.22, H.escape(a), H.escape(b), H.escape(c), 1.5 + k * 0.45)
        for k, (a, b, c) in enumerate(msgs))
    return ("head(0)+" + J(
        '<div class="phish-top"><span class="warn rv" style="animation-delay:.1s">&#9888;&#65039;</span>'
        '<div><p class="lede rv" style="animation-delay:.18s;margin:0 0 10px;max-width:none"><b>We follow Facebook and Instagram rules and policies.</b></p>'
        '<p class="lede rv" style="animation-delay:.3s;margin:0;max-width:none"><b style="color:#e02424">NEVER</b> click on <b>“phishing links”</b>. '
        'If you have any doubts, feel free to send us a screenshot.</p></div></div>'
        '<div class="scams">' + cards + '</div>'))

